<?php
declare(strict_types=1);
require_once __DIR__ . '/../../config/config.php';
require_once __DIR__ . '/../../config/database.php';
require_once __DIR__ . '/../../config/functions.php';
require_once __DIR__ . '/../../config/session.php';
require_once __DIR__ . '/lib_salary_advance_policy.php';

Session::start();
$role = (string)Session::getUserRole();
if (!Session::isLoggedIn()) { header('Location: ' . APP_URL . 'login.php'); exit; }
if (!in_array($role, ['financial_manager','admin','fm'], true)) { header('Location: ' . APP_URL . 'index.php'); exit; }
$pdo=db(); $message=''; $error='';
try {
 if($_SERVER['REQUEST_METHOD']==='POST') {
  if(!verify_csrf()) throw new RuntimeException('انتهت صلاحية نموذج الحماية. أعد تحميل الصفحة وحاول مرة أخرى.');
  if(($_POST['action']??'')!=='create_policy') throw new InvalidArgumentException('الإجراء غير صالح.');
  $p=hrSalaryAdvancePolicyValidate($_POST);
  $pdo->beginTransaction();
  try {
   $existing=dbFetchOne('SELECT id FROM hr_salary_advance_policy_versions WHERE effective_from=? LIMIT 1',[$p['effective_from']]);
   if($existing) throw new InvalidArgumentException('يوجد إصدار سياسة بنفس تاريخ السريان بالفعل.');
   $next=dbFetchOne('SELECT COALESCE(MAX(version_no),0)+1 AS next_version FROM hr_salary_advance_policy_versions'); $v=(int)$next['next_version'];
   $sql="INSERT INTO hr_salary_advance_policy_versions (version_no,policy_name,effective_from,notes,allow_any_request_amount,minimum_request_amount,maximum_request_amount,allow_multiple_active_advances,allow_fixed_monthly_repayment,allow_full_eligible_salary_repayment,allow_full_settlement_from_salary,allow_direct_repayment,allow_custom_repayment_terms,maximum_monthly_deduction,maximum_repayment_months,repayment_start_rule,insufficient_salary_rule,eligible_salary_basis,minimum_service_days,probation_allowed,terminated_employee_allowed,require_accounting_verification,allow_early_settlement,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
   $pdo->prepare($sql)->execute([$v,$p['policy_name'],$p['effective_from'],$p['notes'],$p['allow_any_request_amount'],$p['minimum_request_amount'],$p['maximum_request_amount'],$p['allow_multiple_active_advances'],$p['allow_fixed_monthly_repayment'],$p['allow_full_eligible_salary_repayment'],$p['allow_full_settlement_from_salary'],$p['allow_direct_repayment'],$p['allow_custom_repayment_terms'],$p['maximum_monthly_deduction'],$p['maximum_repayment_months'],$p['repayment_start_rule'],$p['insufficient_salary_rule'],$p['eligible_salary_basis'],$p['minimum_service_days'],$p['probation_allowed'],$p['terminated_employee_allowed'],$p['require_accounting_verification'],$p['allow_early_settlement'],Session::getUserID()]);
   $pdo->commit(); $message='تم إنشاء إصدار سياسة السلف رقم V'.$v.' بتاريخ سريان '.$p['effective_from'].'.';
  } catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
 }
} catch(Throwable $e){$error=$e->getMessage();}
$activePolicy=hrSalaryAdvancePolicyGetActive($pdo); $policies=hrSalaryAdvancePolicyGetAll($pdo);
$pageTitle='سياسة السلف على الراتب'; $active='salary_advance_policy'; require_once __DIR__.'/../../includes/header.php';
?>
<div class="container-fluid px-3 pb-4" style="max-width:1500px"><div class="card shadow-sm border-0"><div class="card-body"><h3 class="mb-1">سياسة السلف على الراتب</h3><p class="text-muted small mb-3">سياسة سنوية/مُصدرة من FM وتستخدم كإعدادات افتراضية لطلبات السلف. يمكن تخصيص الشروط لاحقاً لكل طلب دون تعديل السياسة الأصلية.</p><?php if($message):?><div class="alert alert-success py-2"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger py-2"><?=e($error)?></div><?php endif;?><?php if($activePolicy):?><div class="alert alert-info py-2 small">السياسة السارية حالياً: <strong>V<?= (int)$activePolicy['version_no'] ?></strong> — <?=e($activePolicy['policy_name'])?> — <?=e($activePolicy['effective_from'])?></div><?php else:?><div class="alert alert-warning py-2 small">لا توجد سياسة سلف سارية حالياً.</div><?php endif;?><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="create_policy"><div class="row g-3"><div class="col-md-4"><label class="form-label">اسم السياسة *</label><input name="policy_name" class="form-control" required value="سياسة السلف على الراتب"></div><div class="col-md-4"><label class="form-label">تاريخ السريان *</label><input type="date" name="effective_from" class="form-control" min="<?=e(date('Y-m-d',strtotime('+1 day')))?>" required></div><div class="col-md-4"><label class="form-label">أساس الراتب المؤهل</label><select name="eligible_salary_basis" class="form-select"><option value="net_before_advance">صافي الراتب قبل خصم السلفة</option><option value="gross">الراتب الإجمالي</option></select></div><div class="col-12"><hr><strong>قواعد الطلب</strong></div><div class="col-md-3"><label class="form-label"><input type="checkbox" name="allow_any_request_amount" checked> السماح بأي مبلغ مطلوب</label></div><div class="col-md-3"><label class="form-label">الحد الأدنى<input type="number" step="0.01" min="0" name="minimum_request_amount" class="form-control"></label></div><div class="col-md-3"><label class="form-label">الحد الأقصى<input type="number" step="0.01" min="0" name="maximum_request_amount" class="form-control"></label></div><div class="col-md-3"><label class="form-label"><input type="checkbox" name="allow_multiple_active_advances"> السماح بأكثر من سلفة نشطة</label></div><div class="col-12"><hr><strong>طرق السداد</strong></div><div class="col-md-4"><label><input type="checkbox" name="allow_fixed_monthly_repayment" checked> قسط شهري ثابت</label></div><div class="col-md-4"><label><input type="checkbox" name="allow_full_eligible_salary_repayment" checked> خصم كامل الراتب المؤهل</label></div><div class="col-md-4"><label><input type="checkbox" name="allow_full_settlement_from_salary" checked> تسوية كامل الرصيد من الراتب</label></div><div class="col-md-4"><label><input type="checkbox" name="allow_direct_repayment" checked> سداد مباشر</label></div><div class="col-md-4"><label><input type="checkbox" name="allow_custom_repayment_terms" checked> تخصيص شروط السداد لكل طلب</label></div><div class="col-md-4"><label class="form-label">الحد الأقصى للخصم الشهري<input type="number" step="0.01" min="0" name="maximum_monthly_deduction" class="form-control"></label></div><div class="col-md-4"><label class="form-label">أقصى عدد أشهر للسداد<input type="number" min="1" name="maximum_repayment_months" class="form-control"></label></div><div class="col-md-4"><label class="form-label">بدء السداد<select name="repayment_start_rule" class="form-select"><option value="next_payroll">المسير التالي</option><option value="specified_month">شهر يحدده الطلب</option></select></label></div><div class="col-md-4"><label class="form-label">عند عدم كفاية الراتب<select name="insufficient_salary_rule" class="form-select"><option value="available_salary">خصم المتاح وترحيل الباقي</option><option value="skip_month">تجاوز الشهر وترحيل القسط</option></select></label></div><div class="col-12"><hr><strong>الأهلية والضوابط</strong></div><div class="col-md-3"><label class="form-label">الحد الأدنى للخدمة (يوم)<input type="number" min="0" name="minimum_service_days" class="form-control" value="0"></label></div><div class="col-md-3"><label><input type="checkbox" name="probation_allowed" checked> السماح خلال فترة التجربة</label></div><div class="col-md-3"><label><input type="checkbox" name="terminated_employee_allowed"> السماح لمنهي الخدمة</label></div><div class="col-md-3"><label><input type="checkbox" name="require_accounting_verification" checked> إلزام التحقق المحاسبي</label></div><div class="col-md-3"><label><input type="checkbox" name="allow_early_settlement" checked> السماح بالتسوية المبكرة</label></div><div class="col-12"><label class="form-label">ملاحظات<textarea name="notes" class="form-control" rows="2"></textarea></label></div><div class="col-12"><button class="btn btn-primary" type="submit"><i class="fas fa-plus me-1"></i> إنشاء إصدار السياسة</button></div></div></form></div></div><div class="card shadow-sm border-0 mt-3"><div class="card-body"><h5>سجل إصدارات السياسة</h5><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>الإصدار</th><th>الاسم</th><th>السريان</th><th>المبلغ</th><th>السداد</th><th>الأهلية</th><th>أنشأه</th></tr></thead><tbody><?php foreach($policies as $p):?><tr><td><strong>V<?= (int)$p['version_no']?></strong></td><td><?=e($p['policy_name'])?></td><td><?=e($p['effective_from'])?></td><td><?= (int)$p['allow_any_request_amount']?'أي مبلغ':number_format((float)$p['minimum_request_amount'],2).' — '.number_format((float)$p['maximum_request_amount'],2)?></td><td><?= (int)$p['allow_fixed_monthly_repayment']?'شهري ':'' ?><?= (int)$p['allow_full_eligible_salary_repayment']?'كامل الراتب ':'' ?><?= (int)$p['allow_direct_repayment']?'مباشر':'' ?></td><td><?= (int)$p['probation_allowed']?'تجربة مسموحة':'تجربة غير مسموحة' ?></td><td><?=e($p['created_by_name']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
